{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.fresh_mix_score AS WITH alloc_mix AS ( SELECT branch_code, DATE_TRUNC(\'WEEK\', order_date) AS week_start, UPPER(category) AS category, COALESCE(UPPER(style), \'SNITCH\') AS style, COALESCE(UPPER(meta1), \'N/A\') AS meta1, COALESCE(UPPER(meta2), \'N/A\') AS meta2, COALESCE(UPPER(meta3), \'N/A\') AS meta3, SUM(actual_qty) AS actual_units FROM snitch_db.maplemonk.fresh_allocation_tagged WHERE category IS NOT NULL GROUP BY 1,2,3,4,5,6,7 ), alloc_mix_pct AS ( SELECT *, actual_units / NULLIF(SUM(actual_units) OVER (PARTITION BY branch_code, week_start), 0) AS alloc_mix_pct, SUM(actual_units) OVER (PARTITION BY branch_code, week_start) AS week_total_units, COUNT(*) OVER (PARTITION BY branch_code, week_start) AS week_total_combos FROM alloc_mix ), with_zone AS ( SELECT a.*, z.zone AS store_zone, CASE WHEN a.category IN (\'T-SHIRTS\', \'SHIRTS\') AND z.zone IS NOT NULL THEN z.zone ELSE \'ALL\' END AS warehouse_scope FROM alloc_mix_pct a LEFT JOIN snitch_db.maplemonk.store_zone_map z ON a.branch_code = z.branch_code ), compared AS ( SELECT a.branch_code, a.week_start, a.category, a.style, a.meta1, a.meta2, a.meta3, a.actual_units, a.alloc_mix_pct, a.week_total_units, a.week_total_combos, a.store_zone, a.warehouse_scope, COALESCE(s.sales_mix_blended_pct, 0) AS sales_mix_target_pct, COALESCE(w.warehouse_mix_pct, 0) AS warehouse_mix_pct, LEAST(COALESCE(s.sales_mix_blended_pct, 0), COALESCE(w.warehouse_mix_pct, 0)) AS achievable_target_pct, CASE WHEN COALESCE(w.warehouse_mix_pct, 0) < COALESCE(s.sales_mix_blended_pct, 0) THEN \'Yes\' ELSE \'No\' END AS warehouse_constrained_flag, CASE WHEN w.warehouse_mix_pct IS NULL THEN \'Yes\' ELSE \'No\' END AS warehouse_data_missing FROM with_zone a LEFT JOIN snitch_db.maplemonk.fresh_sales_mix_reference s ON a.branch_code = s.branch_code AND a.week_start = s.week_start AND a.category = s.category AND a.style = s.style AND a.meta1 = s.meta1 AND a.meta2 = s.meta2 AND a.meta3 = s.meta3 LEFT JOIN snitch_db.maplemonk.warehouse_availability_mix w ON a.warehouse_scope = w.scope AND a.category = w.category AND a.style = w.style AND a.meta1 = w.meta1 AND a.meta2 = w.meta2 AND a.meta3 = w.meta3 ), scored AS ( SELECT *, ABS(alloc_mix_pct - achievable_target_pct) AS mix_deviation FROM compared ), scored_tiered AS ( SELECT *, CASE WHEN mix_deviation <= 0.05 THEN \'Perfect\' WHEN mix_deviation <= 0.15 THEN \'Okay\' ELSE \'Poor\' END AS combo_deviation_tier FROM scored ), store_rollup AS ( SELECT branch_code, week_start, SUM(mix_deviation * achievable_target_pct) / NULLIF(SUM(achievable_target_pct), 0) AS weighted_mix_deviation FROM scored_tiered GROUP BY branch_code, week_start ) SELECT sc.*, sr.weighted_mix_deviation, CASE WHEN sc.week_total_combos < 5 OR sc.week_total_units < 15 THEN \'Insufficient Volume\' WHEN sr.weighted_mix_deviation IS NULL THEN \'No Data\' WHEN sr.weighted_mix_deviation <= 0.05 THEN \'Perfect\' WHEN sr.weighted_mix_deviation <= 0.15 THEN \'Okay\' ELSE \'Poor\' END AS mix_score FROM scored_tiered sc LEFT JOIN store_rollup sr ON sc.branch_code = sr.branch_code AND sc.week_start = sr.week_start;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            